  B: { modelo: 'gpt-4o',      precio_in: 2.50, precio_out: 10.00, descripcion: 'Agente premium (gpt-4o) + RAG + Juez' },
};
const juez = { modelo_juez: 'gpt-4o', juez_precio_in: 2.50, juez_precio_out: 10.00 };
const preguntas = [
  { q: 'P1', pregunta: 'Si me llega roto el celular, me devuelven la plata?', seccion_esperada: '4.2' },
  { q: 'P2', pregunta: 'Cuanto tarda en llegar un pedido a Mendoza y cuanto sale el envio?', seccion_esperada: '2.1' },
  { q: 'P3', pregunta: 'Puedo pagar en 12 cuotas sin interes?', seccion_esperada: '3.1' },
  { q: 'P4', pregunta: 'Compre unos auriculares in-ear, los abri y me arrepenti. Los puedo devolver?', seccion_esperada: '4.1 + 4.4' },
  { q: 'P5', pregunta: 'Tienen local a la calle para retirar el pedido en persona?', seccion_esperada: 'no figura (debe responder No se)' },
];
const lote_id = 'AB-' + $now.toFormat('yyyyLLdd-HHmmss');
const out = [];
for (const arq of ['A', 'B']) {
  for (const p of preguntas) {
    out.push({ json: { lote_id, run_id: `${arq}-${p.q}`, arquitectura: arq, ...arquitecturas[arq], ...juez, ...p,
      email_cliente: 'cliente.prueba@example.com' } });
  }
}
return out;

// Recuperacion lexica sobre la Base de Conocimiento (equivalente a la busqueda en Airtable): top 2 secciones.
const caso = $('Loop Over Items (1 corrida por vez)').first().json;
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9 ]/g, ' ');
const stop = new Set(['que','los','las','del','por','para','con','una','uno','unos','unas','me','mi','lo','la','el','en','un','se','si','y','o','a','de','al','es','son','hay','tienen','puedo','cuanto','como','cual']);
const tokens = norm(caso.pregunta).split(/\s+/).filter(t => t.length >= 3 && !stop.has(t));
const ranked = $input.all().map(i => i.json).filter(r => r.seccion).map(r => {
  const kw = norm(r.palabras_clave), ti = norm(r.titulo), co = norm(r.contenido);
  let score = 0;
  for (const t of tokens) {
    if (kw.includes(t)) score += 3;
    if (ti.includes(t)) score += 2;
    if (co.includes(t)) score += 1;
  }
  return { ...r, score };
}).filter(r => r.score >= 3).sort((a, b) => b.score - a.score).slice(0, 2);
const contexto = ranked.length
  ? ranked.map(r => `[Seccion ${r.seccion} - ${r.titulo}] ${r.contenido}`).join('\n\n')
  : '(sin fragmentos relevantes en la base de conocimiento)';
return [{ json: { ...caso, contexto, secciones_recuperadas: ranked.map(r => r.seccion).join(', ') || 'ninguna',
  intento: 1, critica_previa: '', respuesta_previa: '',
  tokens_agente_in: 0, tokens_agente_out: 0, tokens_juez_in: 0, tokens_juez_out: 0,
  t_inicio: Date.now() } }];

const estado = $('Estado del intento').first().json;
const r = $input.first().json;
const msg = (r.output || []).find(o => o.type === 'message');
const part = msg && (msg.content || []).find(c => c.type === 'output_text');
const respuesta = part ? (typeof part.text === 'string' ? part.text : JSON.stringify(part.text)) : '';
return [{ json: { ...estado, respuesta,
  tokens_agente_in: estado.tokens_agente_in + (r.usage?.input_tokens || 0),
  tokens_agente_out: estado.tokens_agente_out + (r.usage?.output_tokens || 0) } }];

