const estado = $('Payload JSON para el Juez').first().json;
const r = $input.first().json;
const msg = (r.output || []).find(o => o.type === 'message');
const part = msg && (msg.content || []).find(c => c.type === 'output_text');
let v = part ? part.text : null;
if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { v = null; } }
const valido = v && Number.isInteger(v.exactitud_factual) && ['ACEPTADO', 'CORREGIR', 'RECHAZADO'].includes(v.estado_veredicto);
// Guardrail: si el Juez no devuelve el JSON valido, se escala a humano (el Switch nunca recibe texto libre)
const ver = valido ? v : { exactitud_factual: 1, estado_veredicto: 'RECHAZADO', categoria_error: 'tono_o_formato', critica: 'El Juez no devolvio un JSON valido: revision humana.' };
const tj_in = estado.tokens_juez_in + (r.usage?.input_tokens || 0);
const tj_out = estado.tokens_juez_out + (r.usage?.output_tokens || 0);
const costo_agente = (estado.tokens_agente_in * estado.precio_in + estado.tokens_agente_out * estado.precio_out) / 1e6;
const costo_juez = (tj_in * estado.juez_precio_in + tj_out * estado.juez_precio_out) / 1e6;
const { payload_juez, ...resto } = estado;
return [{ json: { ...resto,
  exactitud_factual: ver.exactitud_factual, estado_veredicto: ver.estado_veredicto,
  categoria_error: ver.categoria_error || 'ninguno', critica: ver.critica || '',
  exactitud_inicial: estado.intento === 1 ? ver.exactitud_factual : estado.exactitud_inicial,
  estado_inicial: estado.intento === 1 ? ver.estado_veredicto : estado.estado_inicial,
  categoria_error_inicial: estado.intento === 1 ? (ver.categoria_error || 'ninguno') : estado.categoria_error_inicial,
  tokens_juez_in: tj_in, tokens_juez_out: tj_out,
  costo_agente_usd: costo_agente, costo_juez_usd: costo_juez, costo_total_usd: costo_agente + costo_juez } }];

// Registro del veredicto para auditoria (repositorio externo: Data Table). Toma el estado del ultimo veredicto.
const s = $('Procesar veredicto + costo').first().json;
const aceptado = s.estado_veredicto === 'ACEPTADO' && s.exactitud_factual >= 4;
const decision = $input.first().json.query?.accion || (aceptado ? 'no_requerida' : 'pendiente_humano');
const ruta = aceptado ? (s.intento === 1 ? 'ACEPTAR (1er intento)' : 'ACEPTAR (tras Self-Healing)') : 'ESCALAR (Human-in-the-loop)';
return [{ json: {
  lote_id: s.lote_id, run_id: s.run_id, arquitectura: s.arquitectura, modelo: s.modelo, pregunta: s.pregunta,
  respuesta_final: s.respuesta, email_cliente: s.email_cliente,
  exactitud_inicial: s.exactitud_inicial, exactitud_factual: s.exactitud_factual,
  estado_inicial: s.estado_inicial, estado_veredicto: s.estado_veredicto,
  categoria_error_inicial: s.categoria_error_inicial, categoria_error: s.categoria_error, critica: s.critica,
  intentos: s.intento, ruta_final: ruta, decision_humana: decision,
  tokens_agente: s.tokens_agente_in + s.tokens_agente_out, tokens_juez: s.tokens_juez_in + s.tokens_juez_out,
  costo_agente_usd: Number(s.costo_agente_usd.toFixed(6)), costo_juez_usd: Number(s.costo_juez_usd.toFixed(6)),
  costo_total_usd: Number(s.costo_total_usd.toFixed(6)), latencia_ms: Date.now() - s.t_inicio, fecha: new Date().toISOString()
} }];

// Dashboard consolidado del Test A/B + proyeccion a 1.000 ejecuciones
const rows = $input.all().map(i => i.json).filter(r => r.run_id).sort((a, b) => a.run_id.localeCompare(b.run_id));
const r2 = x => Math.round(x * 100) / 100, usd = x => Number(x.toFixed(4));
const resumen = {};
for (const arq of ['A', 'B']) {
  const rs = rows.filter(r => r.arquitectura === arq);
  const n = rs.length || 1;
  const sum = f => rs.reduce((a, r) => a + Number(r[f] || 0), 0);
  const aceptadas = rs.filter(r => String(r.ruta_final).startsWith('ACEPTAR')).length;
  const costo_medio = sum('costo_total_usd') / n;
  resumen[arq] = {
    modelo: rs[0]?.modelo, corridas: rs.length,
    exactitud_media_inicial: r2(sum('exactitud_inicial') / n),
    exactitud_media_final: r2(sum('exactitud_factual') / n),
    aceptadas_1er_intento: rs.filter(r => r.estado_inicial === 'ACEPTADO' && r.exactitud_inicial >= 4).length,
    aceptadas_final: aceptadas,
    precision_final_pct: Math.round(aceptadas / n * 100),
    escaladas_a_humano: rs.length - aceptadas,
    reintentos_self_healing: rs.filter(r => r.intentos > 1).length,
    tokens_medios: Math.round((sum('tokens_agente') + sum('tokens_juez')) / n),
    latencia_media_s: r2(sum('latencia_ms') / n / 1000),
    costo_medio_corrida_usd: usd(costo_medio),
    costo_medio_agente_usd: usd(sum('costo_agente_usd') / n),
    costo_medio_juez_usd: usd(sum('costo_juez_usd') / n),
    costo_por_respuesta_aceptada_usd: aceptadas ? usd(sum('costo_total_usd') / aceptadas) : null,
    proyeccion_1000_usd: r2(costo_medio * 1000),
    proyeccion_1000_sin_juez_usd: r2(sum('costo_agente_usd') / n * 1000),
    escalados_proyectados_1000: Math.round((rs.length - aceptadas) / n * 1000),
  };
}
const categorias = {};
for (const r of rows) {
  const c = r.categoria_error_inicial || 'ninguno';
  if (c !== 'ninguno') categorias[c] = (categorias[c] || 0) + 1;
}
const A = resumen.A, B = resumen.B;
let recomendacion;
if (A.precision_final_pct >= B.precision_final_pct && A.costo_medio_corrida_usd <= B.costo_medio_corrida_usd) {
  recomendacion = `Arquitectura A (${A.modelo}): igual o mayor precision final (${A.precision_final_pct}% vs ${B.precision_final_pct}%) a menor costo (USD ${A.proyeccion_1000_usd} vs USD ${B.proyeccion_1000_usd} cada 1.000 ejecuciones).`;
} else if (B.precision_final_pct > A.precision_final_pct) {
  const extra = r2(B.proyeccion_1000_usd - A.proyeccion_1000_usd);
  recomendacion = `Arquitectura B (${B.modelo}) es mas precisa (${B.precision_final_pct}% vs ${A.precision_final_pct}%). Cuesta USD ${extra} mas cada 1.000 ejecuciones, pero evita ${A.escalados_proyectados_1000 - B.escalados_proyectados_1000} escalamientos humanos cada 1.000: conviene si una revision humana cuesta mas de USD ${r2(extra / Math.max(1, A.escalados_proyectados_1000 - B.escalados_proyectados_1000))}.`;
} else {
  recomendacion = `Arquitectura A (${A.modelo}): misma precision que B con menor costo por respuesta aceptada.`;
}
const matriz = rows.map(r => `| ${r.run_id} | ${r.arquitectura} | ${r.modelo} | ${r.exactitud_inicial} -> ${r.exactitud_factual} | ${r.estado_inicial} -> ${r.estado_veredicto} | ${r.categoria_error_inicial} | ${r.intentos} | ${r.ruta_final} | ${r.tokens_agente + r.tokens_juez} | ${Number(r.costo_total_usd).toFixed(5)} |`).join('\n');
return [{ json: { lote_id: rows[0]?.lote_id, corridas: rows.length, resumen_por_arquitectura: resumen,
  categorias_error_mas_frecuentes: Object.entries(categorias).sort((a, b) => b[1] - a[1]).map(([categoria, cantidad]) => ({ categoria, cantidad })),
  recomendacion_borrador: recomendacion,
  matriz_markdown: '| Corrida | Arq | Modelo | Exactitud | Veredicto | Error inicial | Intentos | Ruta final | Tokens | Costo USD |\n|---|---|---|---|---|---|---|---|---|---|\n' + matriz,
  matriz_ab: rows } }];
